import{R as t,e as o,f as i,U as n}from"./chunks/framework.ywem4qy5.js";const h=JSON.parse('{"title":"Stripe","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/payments/stripe.md","filePath":"integrations/payments/stripe.md","lastUpdated":1775908585000}'),r={name:"integrations/payments/stripe.md"};function s(a,e,l,c,p,d){return o(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="stripe" tabindex="-1">Stripe <a class="header-anchor" href="#stripe" aria-label="Permalink to &quot;Stripe&quot;">​</a></h1><p>Follow the below steps to connect to the Stripe API.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Payments</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select <strong>Stripe</strong> as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-stripe-api" tabindex="-1">Step 2. Connect to the Stripe API <a class="header-anchor" href="#step-2-connect-to-the-stripe-api" aria-label="Permalink to &quot;Step 2. Connect to the Stripe API&quot;">​</a></h3><ol><li>Go to your <a href="https://dashboard.stripe.com/apikeys" target="_blank">Stripe Developers - API Keys</a> page in your Stripe dashboard.</li><li>On the top-right of your screen, ensure the <strong>Test Mode</strong> lightswitch is in the <strong>off</strong> position if you wish to use Live details, or <strong>on</strong> if you wish to use Test details.</li><li>Copy the <strong>Publishable Key</strong> from Stripe and paste in the <strong>Publishable Key</strong> field in Formie.</li><li>Copy the <strong>Secret Key</strong> from Stripe and paste in the <strong>Secret Key</strong> field in Formie.</li><li>We <strong>strongly recommend</strong> you use <code>.env</code> variables to store these keys.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Refresh</strong> button in the right-hand sidebar.</li></ol><h3 id="step-4-configure-webhooks-for-subscriptions" tabindex="-1">Step 4. Configure Webhooks (for subscriptions) <a class="header-anchor" href="#step-4-configure-webhooks-for-subscriptions" aria-label="Permalink to &quot;Step 4. Configure Webhooks (for subscriptions)&quot;">​</a></h3><ol><li>In order for subscriptions to work, you must populate some settings for webhooks.</li><li>In Stripe, on the left-hand sidebar menu, click <strong>Developers</strong>.</li><li>On the top sub-menu, click <strong>Webhooks</strong>.</li><li>Click the <strong>Create an event destination</strong> button.</li><li>Copy the <strong>Redirect URI</strong> from the Formie integration settings and paste in the <strong>Endpoint URL</strong> in Stripe.</li><li>Click the <strong>Select Events</strong> button under the &quot;Select events to listen to&quot; heading.</li><li>We recommend emitting all possible events, but the required events are: <ul><li><code>customer.subscription.created</code></li><li><code>customer.subscription.deleted</code></li><li><code>customer.subscription.updated</code></li><li><code>invoice.created</code></li><li><code>invoice.payment_failed</code></li><li><code>invoice.payment_succeeded</code></li><li><code>payment_intent.succeeded</code></li><li><code>payment_intent.payment_failed</code></li><li><code>payment_intent.canceled</code></li><li><code>plan.deleted</code></li><li><code>plan.updated</code></li></ul></li><li>Once created look for the <strong>Signing secret</strong> item and click <strong>Reveal Secret</strong>.</li><li>Copy the <strong>Signing secret</strong> from Stripe and paste in the <strong>Webhook Signing Secret</strong> field in Formie.</li></ol><h3 id="step-5-field-setting" tabindex="-1">Step 5. Field Setting <a class="header-anchor" href="#step-5-field-setting" aria-label="Permalink to &quot;Step 5. Field Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Add a <strong>Payment</strong> field to your form.</li><li>Select Stripe for the <strong>Payment Provider</strong>.</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Your form <strong>must</strong> use the Ajax (Client-side) submission method when using the Stripe payment integration in your form.</p></div><p>The Stripe payment integration supports both once-off payments and subscription-based payments.</p>',14)])])}const u=t(r,[["render",s]]);export{h as __pageData,u as default};
